"kind": "propose",
"summary": "The app's memory limit is insufficient for its long-running usage, causing OOM kills. Increasing the limit to 1.25Gi will accommodate peak memory usage.",
"hypotheses": [
  {
    "root_cause_class": "memory_limit_too_low",
    "summary": "The app's memory usage grew over time (oom_after_long_run) and reached 100% of its 1Gi limit before being OOMKilled, indicating the limit is too low for its steady-state usage.",
    "supporting": ["oom_killed_current_revision", "memory_at_limit_before_kill", "oom_after_long_run", "memory_data_available"],
    "contradicting": [],
    "missing": ["earlier_revision_healthy"],
    "status": "supported"
  },
  {
    "root_cause_class": "memory_leak",
    "summary": "The logs show memory usage increasing over time but no evidence of unbounded growth (heap flat after GC), ruling out a leak.",
    "supporting": ["oom_after_long_run"],
    "contradicting": ["memory_at_limit_before_kill"],
    "missing": ["peak_memory_growth"],
    "status": "refuted"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "sessions",
    "uid": "uid-deployment-sessions"
  },
  "params": {
    "containers": {
      "app": {
        "limits": {
          "memory": "1228Mi"
        }
      }
    }
  },
  "expected_effect": "The memory limit will be increased to 1228Mi (1.25Gi), allowing the app to use up to 1.25Gi before being OOMKilled.",
  "rationale": "The app's memory usage grew over time (oom_after_long_run) and reached 100% of its 1Gi limit before being OOMKilled. The logs show steady memory growth matching expected cache sizing, not a leak. Increasing the limit by 25% (to 1228Mi) will accommodate peak usage without unnecessary resource allocation.",
  "cited_evidence_ids": ["ev-container_memory", "ev-pod_states", "ev-rollout_history", "ev-container_logs_tail"],
  "cited_predicates": ["oom_killed_current_revision", "memory_at_limit_before_kill", "oom_after_long_run"]
}
}
